#include "Media.hpp"
namespace Davis::Media {
static u32 be32(const u8*p){return ((u32)p[0]<<24)|((u32)p[1]<<16)|((u32)p[2]<<8)|p[3];}
bool ByteStream::Read(void*out,u32 n){if(!out||pos>bytes||n>bytes-pos)return false;u8*d=(u8*)out;for(u32 i=0;i<n;i++)d[i]=data[pos+i];pos+=n;return true;} bool ByteStream::Seek(u32 p){if(p>bytes)return false;pos=p;return true;}
ImageFormat DetectImage(const u8*d,u32 n){if(!d)return ImageFormat::Unknown;if(n>=2&&d[0]=='B'&&d[1]=='M')return ImageFormat::Bmp;if(n>=8&&d[0]==0x89&&d[1]=='P'&&d[2]=='N'&&d[3]=='G'&&d[4]==0x0d&&d[5]==0x0a&&d[6]==0x1a&&d[7]==0x0a)return ImageFormat::Png;if(n>=3&&d[0]==0xff&&d[1]==0xd8&&d[2]==0xff)return ImageFormat::Jpeg;if(n>=6&&d[0]=='G'&&d[1]=='I'&&d[2]=='F')return ImageFormat::Gif;if(n>=12&&d[0]=='R'&&d[1]=='I'&&d[2]=='F'&&d[8]=='W'&&d[9]=='E'&&d[10]=='B'&&d[11]=='P')return ImageFormat::WebP;if(n>=4&&d[0]==0&&d[1]==0&&d[2]==1&&d[3]==0)return ImageFormat::Ico;return ImageFormat::Unknown;}
bool ProbeImage(const u8*d,u32 n,ImageInfo&o){o={};o.format=DetectImage(d,n);if(o.format==ImageFormat::Png&&n>=24){o.width=be32(d+16);o.height=be32(d+20);return o.width&&o.height;}if(o.format==ImageFormat::Gif&&n>=10){o.width=d[6]|((u32)d[7]<<8);o.height=d[8]|((u32)d[9]<<8);o.animated=true;return true;}if(o.format==ImageFormat::Jpeg&&n>=4){u32 p=2;while(p+4<=n){if(d[p++]!=0xff)continue;while(p<n&&d[p]==0xff)p++;if(p>=n)break;u8 m=d[p++];if(m==0xd8||m==0xd9||(m>=0xd0&&m<=0xd7))continue;if(p+2>n)break;u16 L=(u16)(((u16)d[p]<<8)|d[p+1]);if(L<2||p+L>n)break;if((m>=0xc0&&m<=0xc3)&&L>=8){o.height=((u32)d[p+3]<<8)|d[p+4];o.width=((u32)d[p+5]<<8)|d[p+6];return o.width&&o.height;}p+=L;}}return o.format!=ImageFormat::Unknown;}
}
